 private static PrestamoProgramaForm form(long concepto,long emp,LocalDate inicio){var f=new PrestamoProgramaForm();f.setEmpleadoId(emp);f.setEmpleadoTexto("Persona Préstamo");f.setConceptoId(concepto);f.setConceptoTexto("PREST-QA · Recuperación de préstamo");f.setConceptoVersion(0L);f.setCapital(new BigDecimal("120"));f.setCuotas(2);f.setInicio(inicio);f.setMotivo("Préstamo ficticio para pruebas aisladas");return f;}
 private static EntregarPrestamoForm entrega(long version,long cuenta){var f=new EntregarPrestamoForm();f.setVersion(version);f.setCuentaId(cuenta);f.setCuentaTexto("Cuenta ficticia");f.setMotivoPagoId(530000L);f.setMotivoPagoTexto("Egreso ficticio");f.setReferencia("ENTREGA-PREST-QA");f.setMotivo("Entrega ficticia del principal");return f;}
 private static PagoIndividualNominaForm individual(long periodo,long emp,String importe){var f=new PagoIndividualNominaForm();f.setPeriodoId(periodo);f.setEmpleadoId(emp);f.setMotivoPagoId(530000L);f.setReferencia("NOM-PREST-QA");f.setMotivo("Pago ficticio con recuperación de préstamo");f.getFuentes().getFirst().setCuentaId(530000L);f.getFuentes().getFirst().setImporte(new BigDecimal(importe));return f;}
 private static long periodo(ProgramacionNominaService s,String codigo,LocalDate ini,LocalDate fin){var f=new PeriodoNominaForm();f.setCodigo(codigo);f.setInicio(ini);f.setFin(fin);f.setPago(fin);return s.guardarPeriodo(null,f);}
 private static BigDecimal saldo(JdbcTemplate j,long id){return j.queryForObject("SELECT coalesce((SELECT saldo_posterior FROM movimiento_financiero WHERE cuenta_id=c.id ORDER BY secuencia_cuenta DESC LIMIT 1),saldo_inicial) FROM cuenta_financiera c WHERE id=?",BigDecimal.class,id);}
